  ELT(((`n` - 1) MOD 6) + 1, 'BACKLOG', 'TODO', 'IN_PROGRESS', 'REVIEW', 'DONE', 'BLOCKED'),
  @base_task_part + (((`n` - 1) MOD 480) + 1),
  @base_milestone + (((`n` - 1) MOD 240) + 1),
  @base_user + (((`n` - 1) MOD 100) + 1),
  ELT(((`n` - 1) MOD 4) + 1, 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'),
