  ELT(((`n` - 1) MOD 10) + 1, 'coupon', 'hotel', 'premium', 'membership', 'limited', 'family', 'event', 'brand', 'benefit', 'review'),
  ELT(((`n` - 1) MOD 3) + 1, 'OCR', 'LLM', 'RULE'),
  ROUND(0.1 + MOD(`n`, 90) / 100, 2),
  NOW(),
  NOW()
FROM `_dumass_seq` WHERE `n` <= 240;

